def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Locate the center rows of 3x3 motifs and full-height 2 dividers.
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]==2 and all(grid[rr][cc]==3 for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                centers.append((r,c))
    divcols=[c for c in range(w) if all(grid[r][c]==2 for r in range(h))]
    # Each motif's center row is extended across the grid. At each divider
    # crossing on that row, draw a 1-colored 3x3 ring around its 2 center.
    for r,c in centers:
        for x in range(w):
            if grid[r][x]==0: out[r][x]=1
        for x in divcols:
            if abs(x-c)<=1: continue
            for rr in range(max(0,r-1),min(h,r+2)):
                for cc in range(max(0,x-1),min(w,x+2)):
                    if grid[rr][cc]==0: out[rr][cc]=1
    return out
