def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]==2 and all(grid[rr][cc]==3 for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                centers.append((r,c))
    # A motif sends a straight line along the axis perpendicular to the grid's
    # repeated dividers. At each crossed divider, the beam widens by one cell.
    vertical=[c for c in range(w) if all(grid[r][c]==2 for r in range(h))]
    horizontal=[r for r in range(h) if all(grid[r][c]==2 for c in range(w))]
    for r,c in centers:
        if len(vertical)>=len(horizontal):
            for x in range(w):
                if grid[r][x]==0: out[r][x]=1
            for x in vertical:
                if x==c: continue
                for rr in (r-1,r+1):
                    for cc in (x-1,x,x+1):
                        if 0<=rr<h and 0<=cc<w and grid[rr][cc]==0: out[rr][cc]=1
        else:
