                if grid[y][c]==0: out[y][c]=1
            for y in horizontal:
                if y==r: continue
                for rr in (y-1,y,y+1):
                    for cc in (c-1,c+1):
                        if 0<=rr<h and 0<=cc<w and grid[rr][cc]==0: out[rr][cc]=1
    return out
