def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(grid),len(grid[0])
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]==2 and all(grid[rr][cc]==3 for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))): centers.append((r,c))
    divcols=[c for c in range(w) if sum(grid[y][c]==2 for y in range(h))>=h-3]
    for r,c in centers:
        for x in range(w):
            if grid[r][x]==0: out[r][x]=1
        for x in divcols:
            for rr in (r-1,r+1):
                for cc in (x-1,x+1):
                    if 0<=rr<h and 0<=cc<w and grid[rr][cc]==0: out[rr][cc]=1
    return out
